import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"First Login and Network Setup","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/operations/first-login-and-network-setup.md"},"headers":[],"relativePath":"sovereign-os/guides/first-login-and-network-setup.md","filePath":"sovereign-os/guides/first-login-and-network-setup.md"}'),n={name:"sovereign-os/guides/first-login-and-network-setup.md"};function h(p,s,l,o,d,r){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="first-login-and-network-setup" tabindex="-1">First Login and Network Setup <a class="header-anchor" href="#first-login-and-network-setup" aria-label="Permalink to &quot;First Login and Network Setup&quot;">​</a></h1><p><strong>Status:</strong> Implemented; physical image verification pending</p><p>This guide defines the Phase 01 preview onboarding flow. Images released before the bootstrap-account implementation do not provide this behavior.</p><h2 id="_1-boot-on-a-trusted-ethernet-network" tabindex="-1">1. Boot on a Trusted Ethernet Network <a class="header-anchor" href="#_1-boot-on-a-trusted-ethernet-network" aria-label="Permalink to &quot;1. Boot on a Trusted Ethernet Network&quot;">​</a></h2><p>Flash the image, connect Ethernet, and power on the Raspberry Pi. Do not expose the preview appliance directly to the internet. Allow several minutes for the first boot, then verify discovery from another computer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign.local</span></span></code></pre></div><p>If <code>.local</code> discovery is unavailable, find the address in the router&#39;s DHCP client list and substitute it for <code>sovereign.local</code> below.</p><h2 id="_2-perform-the-mandatory-first-login" tabindex="-1">2. Perform the Mandatory First Login <a class="header-anchor" href="#_2-perform-the-mandatory-first-login" aria-label="Permalink to &quot;2. Perform the Mandatory First Login&quot;">​</a></h2><p>Connect with the preview bootstrap account:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign@sovereign.local</span></span></code></pre></div><p>Use <code>sovereign</code> as the initial password. SSH will require a new password before opening the shell. Choose a unique password that is not used for another account. The initial credential is public and must not remain active.</p><p>The expected interaction is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sovereign@sovereign.local&#39;s password: sovereign</span></span>
<span class="line"><span>WARNING: Your password has expired.</span></span>
<span class="line"><span>You must change your password now and login again!</span></span>
<span class="line"><span>Current password: sovereign</span></span>
<span class="line"><span>New password: &lt;your-new-device-password&gt;</span></span>
<span class="line"><span>Retype new password: &lt;your-new-device-password&gt;</span></span></code></pre></div><p>The SSH connection may close after the change. Reconnect with the new password:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign@sovereign.local</span></span></code></pre></div><h2 id="_3-retrieve-the-pi-hole-password" tabindex="-1">3. Retrieve the Pi-hole Password <a class="header-anchor" href="#_3-retrieve-the-pi-hole-password" aria-label="Permalink to &quot;3. Retrieve the Pi-hole Password&quot;">​</a></h2><p>The Pi-hole password is unique to the device and remains separate from the Linux account password:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/sovereign/secrets/pihole-admin-password</span></span></code></pre></div><p>Sign in at:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://sovereign.local/dns/admin/</span></span></code></pre></div><p>To replace the generated Pi-hole password, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign-pihole-password</span></span></code></pre></div><p>The command prompts without echoing the new value, updates Pi-hole, and updates the root-owned persistent secret used when the container is recreated. The Linux login password and Pi-hole password remain separate.</p><h2 id="_4-add-an-ssh-key" tabindex="-1">4. Add an SSH Key <a class="header-anchor" href="#_4-add-an-ssh-key" aria-label="Permalink to &quot;4. Add an SSH Key&quot;">​</a></h2><p>On the client computer, create a key if needed:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span></span></code></pre></div><p>Install it on the appliance:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-copy-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign@sovereign.local</span></span></code></pre></div><p>Open a second terminal and verify key authentication before changing the SSH server policy:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PasswordAuthentication=no</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign@sovereign.local</span></span></code></pre></div><p>After that succeeds, disable password authentication on the appliance with a local override that takes precedence over image and Imager defaults:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s\\n&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;PermitRootLogin no&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;PasswordAuthentication no&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;KbdInteractiveAuthentication no&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config.d/90-local-auth.conf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config.d/90-local-auth.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sshd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div><p>Keep the verified session open until a new key-authenticated session succeeds. If the key test fails, do not disable password authentication.</p><p>To re-enable password authentication later from an existing key-authenticated session:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s\\n&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;PermitRootLogin no&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;PasswordAuthentication yes&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config.d/90-local-auth.conf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config.d/90-local-auth.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sshd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div><h2 id="_5-configure-wi-fi-later" tabindex="-1">5. Configure Wi-Fi Later <a class="header-anchor" href="#_5-configure-wi-fi-later" aria-label="Permalink to &quot;5. Configure Wi-Fi Later&quot;">​</a></h2><p>Set the regulatory country first, replacing <code>DE</code> with the correct two-letter country code, and reboot to apply it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;options cfg80211 ieee80211_regdom=DE&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/modprobe.d/cfg80211_regdomain.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span></code></pre></div><p>Reconnect over Ethernet after the reboot, then connect using IWD:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iwctl</span></span></code></pre></div><p>At the interactive prompt:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>device list</span></span>
<span class="line"><span>station wlan0 scan</span></span>
<span class="line"><span>station wlan0 get-networks</span></span>
<span class="line"><span>station wlan0 connect &quot;YOUR_WIFI_NAME&quot;</span></span>
<span class="line"><span>exit</span></span></code></pre></div><p>IWD prompts for the Wi-Fi passphrase without placing it in shell history and stores the resulting profile root-only. Confirm connectivity before removing Ethernet:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> address</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wlan0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign.local</span></span></code></pre></div><h2 id="_6-recover-access" tabindex="-1">6. Recover Access <a class="header-anchor" href="#_6-recover-access" aria-label="Permalink to &quot;6. Recover Access&quot;">​</a></h2><p>If password login still works but the SSH key does not, log in with the device password, remove the local hardening override if present, and repeat the key installation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config.d/90-local-auth.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sshd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div><p>If key authentication works but the Linux password was forgotten, reset it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign</span></span></code></pre></div><p>If neither authentication method works, shut down the Pi, attach the storage to a Linux system that can safely write ext4, mount the root partition, and add a trusted public key to <code>/home/sovereign/.ssh/authorized_keys</code>. Preserve ownership as UID/GID 1000 and modes <code>0700</code> for <code>.ssh</code> and <code>0600</code> for <code>authorized_keys</code>. macOS does not provide safe native ext4 write support.</p><p>Reflashing the complete disk image is the final recovery option and erases the existing partition table, including <code>/data</code>. Back up Pi-hole state before a reflash whenever access to the data partition is still possible.</p><h2 id="recovery-notes" tabindex="-1">Recovery Notes <a class="header-anchor" href="#recovery-notes" aria-label="Permalink to &quot;Recovery Notes&quot;">​</a></h2><ul><li><code>Permission denied (publickey)</code> on an older image means that image has no usable bootstrap password flow; reflash a release that implements this ADR.</li><li>The Linux password and Pi-hole administrator password are intentionally different.</li><li>If the bootstrap password was not changed, treat the device as unclaimed and disconnect it from untrusted networks.</li><li>Do not disable password authentication until key authentication has been tested in a separate session.</li></ul>`,53)])])}const g=i(n,[["render",h]]);export{k as __pageData,g as default};
